mapper.select:
SELECT 
FROM coupon_seckill_order
WHERE order_no = #{orderNo} AND user_id = #{userId}

SELECT 
FROM coupon_seckill_order
WHERE user_id = #{userId}

    AND status = #{status}

ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM coupon_seckill_order
WHERE user_id = #{userId}

    AND status = #{status}

SELECT id, coupon_id, order_no
FROM coupon_seckill_order
WHERE status = 1 AND expire_time <= #{now}
ORDER BY id ASC
LIMIT #{limit}

SELECT COALESCE(SUM(pay_amount), 0)
FROM coupon_seckill_order
WHERE status IN (2, 4)
  AND pay_time >= #{start} AND pay_time < #{end}

    AND pay_type = #{channel}

SELECT COALESCE(SUM(pay_amount), 0)
FROM coupon_seckill_order
WHERE status = 4
  AND refund_time >= #{start} AND refund_time < #{end}

    AND pay_type = #{channel}

SELECT DATE_FORMAT(pay_time, '%Y-%m-%d') AS date_key, COALESCE(SUM(pay_amount), 0) AS amount FROM coupon_seckill_order WHERE status IN (2, 4) AND pay_time >= #{start} AND pay_time < #{end}
AND pay_type = #{channel}
GROUP BY DATE_FORMAT(pay_time, '%Y-%m-%d') ORDER BY date_key

SELECT DATE_FORMAT(refund_time, '%Y-%m-%d') AS date_key, COALESCE(SUM(pay_amount), 0) AS amount FROM coupon_seckill_order WHERE status = 4 AND refund_time >= #{start} AND refund_time < #{end}
AND pay_type = #{channel}
GROUP BY DATE_FORMAT(refund_time, '%Y-%m-%d') ORDER BY date_key

SELECT COALESCE(pay_type, 'Unknown') AS channel, COALESCE(SUM(pay_amount), 0) AS amount, COUNT(*) AS order_count FROM coupon_seckill_order WHERE status IN (2, 4) AND pay_time >= #{start} AND pay_time < #{end}
AND pay_type = #{channel}
GROUP BY COALESCE(pay_type, 'Unknown') ORDER BY amount DESC
